// ---- BEGIN contract header (generated by the harness; do not redefine) ----
#include <metal_stdlib>
#include <metal_simdgroup>
#include <metal_simdgroup_matrix>
using namespace metal;
constant constexpr uint M = 2048u;
constant constexpr uint N = 2048u;
constant constexpr uint K = 2048u;
constant constexpr uint BLOCK_M = 64u;
constant constexpr uint BLOCK_N = 64u;
constant constexpr uint BLOCK_K = 32u;
// ---- END contract header ----

combos.naive_msl:
kernel void gemm_kernel(device const half* A [[buffer(0)]],
                       device const half* B [[buffer(1)]],
                       device half* C [[buffer(2)]],
                       uint2 tg [[threadgroup_position_in_grid]],
                       uint lid [[thread_index_in_threadgroup]]) {
    threadgroup half As[BLOCK_M][BLOCK_K];
    threadgroup half Bs[BLOCK_K][BLOCK_N];
    const uint m0 = tg.y * BLOCK_M, n0 = tg.x * BLOCK_N;
    const uint tr = lid / 8, tc = lid % 8;            // each thread owns a 4 x 8 output tile
    float acc[4][8];
    for (uint i = 0; i < 4; ++i) for (uint j = 0; j < 8; ++j) acc[i][j] = 0.0f;
    for (uint k0 = 0; k0 < K; k0 += BLOCK_K) {
        for (uint i = lid; i < BLOCK_M * BLOCK_K; i += 128) {
            uint r = i / BLOCK_K, c = i % BLOCK_K;
            As[r][c] = A[(ulong)(m0 + r) * K + k0 + c];
        }
        for (uint i = lid; i < BLOCK_K * BLOCK_N; i += 128) {
            uint r = i / BLOCK_N, c = i % BLOCK_N;
            Bs[r][c] = B[(ulong)(k0 + r) * N + n0 + c];
        }
        threadgroup_barrier(mem_flags::mem_threadgroup);
        for (uint kk = 0; kk < BLOCK_K; ++kk) {
            float a[4], b[8];
            for (uint i = 0; i < 4; ++i) a[i] = float(As[tr * 4 + i][kk]);
            for (uint j = 0; j < 8; ++j) b[j] = float(Bs[kk][tc * 8 + j]);
            for (uint i = 0; i < 4; ++i) for (uint j = 0; j < 8; ++j) acc[i][j] += a[i] * b[j];
        }
        threadgroup_barrier(mem_flags::mem_threadgroup);
    }
    for (uint i = 0; i < 4; ++i)
        for (uint j = 0; j < 8; ++j)
            C[(ulong)(m0 + tr * 4 + i) * N + n0 + tc * 8 + j] = half((acc[i][j]));
}

